import java.util.*;

class Solution {
  private int[][] dist;
  private int[][] memo;
  private int n;
  private final int[] dx = {1, 1, 2, 2, -1, -1, -2, -2};
  private final int[] dy = {2, -2, 1, -1, 2, -2, 1, -1};

  public int maxMoves(int kx, int ky, int[][] positions) {
    n = positions.length;
    int[][] points = new int[n + 1][2];
    points[0] = new int[] {kx, ky};
    for (int i = 0; i < n; i++) points[i + 1] = positions[i];
    dist = new int[n + 1][n + 1];
    for (int s = 0; s <= n; s++) bfs(points, s, points[s]);
    memo = new int[1 << n][n + 1];
    for (int[] row : memo) Arrays.fill(row, -1);
    return dfs(0, 0);
  }

  private void bfs(int[][] points, int source, int[] start) {
    int[][] d = new int[50][50];
    for (int[] row : d) Arrays.fill(row, -1);
    ArrayDeque<int[]> queue = new ArrayDeque<>();
    queue.offer(new int[] {start[0], start[1]});
    d[start[0]][start[1]] = 0;
    while (!queue.isEmpty()) {
      int[] p = queue.poll();
      for (int z = 0; z < 8; z++) {
        int x = p[0] + dx[z], y = p[1] + dy[z];
        if (x >= 0 && x < 50 && y >= 0 && y < 50 && d[x][y] < 0) {
          d[x][y] = d[p[0]][p[1]] + 1;
          queue.offer(new int[] {x, y});
        }
      }
    }
    for (int i = 0; i <= n; i++) dist[source][i] = d[points[i][0]][points[i][1]];
  }

  private int dfs(int mask, int at) {
    if (mask == (1 << n) - 1) return 0;
    if (memo[mask][at] != -1) return memo[mask][at];
    boolean maximize = (Integer.bitCount(mask) % 2 == 0);
    int result = maximize ? 0 : Integer.MAX_VALUE;
    for (int i = 0; i < n; i++)
      if ((mask & (1 << i)) == 0) {
        int value = dist[at][i + 1] + dfs(mask | (1 << i), i + 1);
        result = maximize ? Math.max(result, value) : Math.min(result, value);
      }
    return memo[mask][at] = result;
  }
}
